class Solution:
    def numDecodings(self, s: str) -> int:
        prev, cur = 0, 1  # dp[i-2] placeholder, dp[0]
        for i in range(1, len(s) + 1):
            nxt = 0
            if s[i - 1] != '0':
                nxt += cur
            if i > 1 and 10 <= int(s[i - 2:i]) <= 26:
                nxt += prev
            prev, cur = cur, nxt
        return cur
